"""hash8 helper: FNV-1a 64 folded to 32 bits."""


def fnv1a64(data: bytes, h: int = 0xcbf29ce484222325) -> int:
    for b in data:
        h ^= b
        h = (h * 0x100000001b3) & 0xFFFFFFFFFFFFFFFF
    return h


def fold32(h: int) -> int:
    return ((h >> 32) ^ h) & 0xFFFFFFFF


def hash8(s) -> str:
    if isinstance(s, str):
        s = s.encode()
    return "%08x" % fold32(fnv1a64(s))


if __name__ == "__main__":
    import sys
    for a in sys.argv[1:]:
        print(repr(a), hash8(a))

