// Unwind FNV-1a: find the 64-bit FNV state after an unknown prefix X such that
// fold32(fnv(X + S_k)) == T_k for all k (S_k known suffixes).
// Input lines (stdin):  label<TAB>S1hex:T1<TAB>S2hex:T2<TAB>...   (at least 2 pairs)
// Output: label and recovered prefix state for each solution.
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <omp.h>

#define P 0x100000001b3ULL

static uint64_t inv64(uint64_t a) {
    uint64_t x = a; // Newton iteration for inverse mod 2^64 (a odd)
    for (int i = 0; i < 6; i++) x *= 2 - a * x;
    return x;
}

static int hexval(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

typedef struct {
    unsigned char s[512];
    int n;
    uint32_t t;
} Pair;

int main(void) {
    uint64_t PINV = inv64(P);
    char *line = NULL;
    size_t cap = 0;
    ssize_t len;
    while ((len = getline(&line, &cap, stdin)) > 0) {
        if (line[len - 1] == '\n') line[--len] = 0;
        if (len == 0) continue;
        char *save = NULL;
        char *label = strtok_r(line, "\t", &save);
        Pair pairs[64];
        int np = 0;
        char *tok;
        while ((tok = strtok_r(NULL, "\t", &save)) && np < 64) {
            char *colon = strrchr(tok, ':');
            if (!colon) continue;
            *colon = 0;
            int hl = strlen(tok);
            pairs[np].n = hl / 2;
            for (int i = 0; i < hl / 2; i++) pairs[np].s[i] = hexval(tok[2 * i]) * 16 + hexval(tok[2 * i + 1]);
            pairs[np].t = (uint32_t)strtoul(colon + 1, NULL, 16);
            np++;
        }
        if (np < 2) continue;
        const Pair *p0 = &pairs[0];
        int found = 0;
#pragma omp parallel for schedule(static) reduction(+ : found)
        for (int64_t hi = 0; hi < (1LL << 32); hi++) {
            uint64_t lo = ((uint64_t)hi) ^ p0->t;
            uint64_t h = ((uint64_t)hi << 32) | lo;
            for (int i = p0->n - 1; i >= 0; i--) h = (h * PINV) ^ p0->s[i];
            // h = state after X
            int ok = 1;
            for (int k = 1; k < np && ok; k++) {
                uint64_t g = h;
                for (int i = 0; i < pairs[k].n; i++) g = (g ^ pairs[k].s[i]) * P;
                uint32_t f = (uint32_t)(g >> 32) ^ (uint32_t)g;
                if (f != pairs[k].t) ok = 0;
            }
            if (ok) {
#pragma omp critical
                {
                    printf("%s\tSTATE=%016llx\n", label, (unsigned long long)h);
                    fflush(stdout);
                }
                found++;
            }
        }
        fprintf(stderr, "%s: %d solutions\n", label, found);
    }
    return 0;
}

