// Enumerate the Cartesian product of slot alternatives, FNV-1a hashing incrementally,
// and print index tuples whose hash8 equals any target.
// Spec (stdin):
//   T <hex32> [<hex32> ...]        targets
//   S                              start a new slot
//   <hex-bytes>                    an alternative (may be empty line "-" for empty string)
//   ...
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define P 0x100000001b3ULL
#define MAXS 16
#define MAXA 4096

static unsigned char *alt[MAXS][MAXA];
static int altn[MAXS][MAXA];
static int nalt[MAXS];
static int nslots = 0;
static uint32_t targets[64];
static int ntargets = 0;
static int idx[MAXS];
static long long count = 0;

static int hexval(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return 0;
}

static void rec(int s, uint64_t h) {
    if (s == nslots) {
        count++;
        uint32_t f = (uint32_t)(h >> 32) ^ (uint32_t)h;
        for (int t = 0; t < ntargets; t++) {
            if (f == targets[t]) {
                printf("M %d", t);
                for (int i = 0; i < nslots; i++) printf(" %d", idx[i]);
                printf("\n");
            }
        }
        return;
    }
    for (int a = 0; a < nalt[s]; a++) {
        uint64_t g = h;
        const unsigned char *p = alt[s][a];
        int n = altn[s][a];
        for (int i = 0; i < n; i++) g = (g ^ p[i]) * P;
        idx[s] = a;
        rec(s + 1, g);
    }
}

int main(void) {
    char *line = NULL;
    size_t cap = 0;
    ssize_t len;
    while ((len = getline(&line, &cap, stdin)) > 0) {
        if (line[len - 1] == '\n') line[--len] = 0;
        if (line[0] == 'T' && line[1] == ' ') {
            char *p = line + 2;
            char *tok;
            while ((tok = strtok(p, " "))) {
                targets[ntargets++] = (uint32_t)strtoul(tok, NULL, 16);
                p = NULL;
            }
        } else if (strcmp(line, "S") == 0) {
            nslots++;
        } else {
            int s = nslots - 1;
            int a = nalt[s]++;
            if (strcmp(line, "-") == 0) {
                alt[s][a] = NULL;
                altn[s][a] = 0;
            } else {
                int n = len / 2;
                alt[s][a] = malloc(n + 1);
                for (int i = 0; i < n; i++) alt[s][a][i] = hexval(line[2 * i]) * 16 + hexval(line[2 * i + 1]);
                altn[s][a] = n;
            }
        }
    }
    rec(0, 0xcbf29ce484222325ULL);
    fprintf(stderr, "count=%lld\n", count);
    return 0;
}

