#!/usr/bin/env python3
"""Template search driver using the C enumerator.

Each slot is a list of (name, fn(datum) -> str). Enumerates datum 0 in C,
then verifies every hit against all data in Python."""
import itertools
import subprocess
import sys
sys.path.insert(0, "/tmp/hatch_search")
from h import hash8

ENUM = "/tmp/hatch_search/enum"


class D:
    def __init__(self, angles, pitch, written, rendered, hid):
        self.angles = angles
        self.pitch = pitch
        self.written = written  # None for default
        self.rendered = rendered
        self.hid = hid


DATA = [
    D([45.0], 5.0, None, "var(--lini-stroke)", "c92119d9"),
    D([45.0], 6.0, None, "var(--lini-stroke)", "fecd99e1"),
    D([30.0], 5.0, None, "var(--lini-stroke)", "0e62e4e4"),
    D([0.0], 5.0, None, "var(--lini-stroke)", "6e072d51"),
    D([45.0], 5.5, None, "var(--lini-stroke)", "66e90a76"),
    D([90.0], 10.0, None, "var(--lini-stroke)", "5737f20f"),
    D([-45.0], 4.0, None, "var(--lini-stroke)", "0d0a0343"),
    D([45.0], 5.0, "red", "red", "a59b54b5"),
    D([45.0], 5.0, "blue", "blue", "98899220"),
    D([45.0], 5.0, "--red", "var(--lini-red)", "57d56072"),
    D([45.0], 5.0, "#ff0000", "#ff0000", "4a899752"),
    D([40.0, 5.0], 5.0, None, "var(--lini-stroke)", "5ad6ca63"),
    D([45.00001], 5.0, None, "var(--lini-stroke)", "92ac7f88"),
    D([45.0], 5.0001, None, "var(--lini-stroke)", "a5356729"),
]


def disp(x):
    if x == int(x) and abs(x) < 1e16:
        return "%d" % int(x)
    return repr(x)


def dbg(x):
    if x == int(x) and abs(x) < 1e16:
        return "%d.0" % int(x)
    return repr(x)


def f4(x):
    s = "%.4f" % x
    if "." in s:
        s = s.rstrip("0").rstrip(".")
    if s == "-0":
        s = "0"
    return s


def f4dbg(x):
    # value rounded to 4 decimals then Debug-printed
    r = round(x * 10000) / 10000
    return dbg(r)


def run_enum(slots, target):
    lines = ["T " + target]
    for slot in slots:
        lines.append("S")
        for name, fn in slot:
            s = fn(DATA[0]).encode()
            lines.append(s.hex() if s else "-")
    p = subprocess.run([ENUM], input="\n".join(lines) + "\n", capture_output=True, text=True)
    hits = []
    for l in p.stdout.splitlines():
        parts = l.split()
        if parts[0] == "M":
            hits.append([int(x) for x in parts[2:]])
    return hits, p.stderr.strip()


def verify(slots, hit):
    keys = []
    for d in DATA:
        key = "".join(slots[i][hit[i]][1](d) for i in range(len(slots)))
        keys.append(key)
        if hash8(key) != d.hid:
            return False, keys
    return True, keys


def const(s):
    return (repr(s), lambda d, s=s: s)


def search(slots, label=""):
    hits, info = run_enum(slots, DATA[0].hid)
    good = []
    for hit in hits:
        ok, keys = verify(slots, hit)
        names = [slots[i][hit[i]][0] for i in range(len(slots))]
        if ok:
            print("FOUND", label, names, repr(keys[0]), flush=True)
            good.append(names)
        else:
            nmatch = sum(1 for d, k in zip(DATA, keys) if hash8(k) == d.hid)
            if nmatch > 1:
                print("partial", nmatch, label, names, repr(keys[0]), flush=True)
    return good, info, len(hits)

