targets = {"4b5d3f30": "lin135 teal blue", "140eca72": "radial red blue", "a94e6447": "gradient red blue"}

cands = []
kinds = {"4b5d3f30": ["linear", "linear-gradient", "linearGradient", "l", "lin", "Linear"],
         "140eca72": ["radial", "radial-gradient", "radialGradient", "r", "rad", "Radial"],
         "a94e6447": ["linear", "linear-gradient", "linearGradient", "l", "lin", "gradient", "Linear"]}
angles = {"4b5d3f30": ["135", "45", "135.0", "45.0", "rotate(45 0.5 0.5)", "rotate(45)"],
          "140eca72": ["", "None", "0", "0.0"],
          "a94e6447": ["135", "45", "135.0", "45.0", "rotate(45 0.5 0.5)", "rotate(45)", "", "None"]}
stops = {"4b5d3f30": [["var(--lini-teal)", "var(--lini-blue)"], ["--teal", "--blue"], ["teal", "blue"]],
         "140eca72": [["red", "blue"]],
         "a94e6447": [["red", "blue"]]}
offs = [None, ("0%", "100%"), ("0", "100"), ("0", "1"), ("0.0", "1.0")]
SEPS = [",", ", ", ";", "; ", ":", "|", "/", "_", "-", " ", "", "\n", "\t", "\x00"]
for t in targets:
    for kind in kinds[t] + [""]:
        for ang in angles[t]:
            for st in stops[t]:
                for off in offs:
                    if off is None:
                        stopstrs = [st]
                    else:
                        stopstrs = [[o + " " + c for o, c in zip(off, st)], [c + " " + o for o, c in zip(off, st)],
                                    [o + "," + c for o, c in zip(off, st)], [o + ":" + c for o, c in zip(off, st)]]
                    for ss in stopstrs:
                        for sep in SEPS:
