"""Compile a box with the given fill values and print gradient defs."""
import re
import subprocess
import sys

EXE = "/workspace/executable"


def run(fills):
    src = "".join("|box#b%d| { fill: %s; }\n" % (i, f) for i, f in enumerate(fills))
    path = "/tmp/hatch_search/gcase.lini"
    open(path, "w").write(src)
    p = subprocess.run([EXE, path], capture_output=True, text=True)
    defs = re.findall(r'(<(linearGradient|radialGradient|pattern) id="([^"]+)".*?</\2>)', p.stdout)
    ids = re.findall(r'data-id="b(\d+)" style="fill: url\(#([^)]+)\)', p.stdout)
    bydef = {d[2]: d[0] for d in defs}
    for i, f in enumerate(fills):
        m = [x for x in ids if int(x[0]) == i]
        if m:
            print("%-50s %s   %s" % (f, m[0][1], bydef.get(m[0][1], "")[:300]))
        else:
            print("%-50s NONE" % f)
    if p.stderr.strip():
        print("STDERR:", p.stderr.strip()[:500])


if __name__ == "__main__":
    run(sys.argv[1:])

