"""Compile each fill value in its own document (avoids in-document dedup) and print the def."""
import re
import subprocess
import sys

EXE = "/workspace/executable"


def one(fill, layout_drawing=False):
    src = ("{ layout: drawing; }\n" if layout_drawing else "") + "|box#b0| { fill: %s; }\n" % fill
    path = "/tmp/hatch_search/gsep.lini"
    open(path, "w").write(src)
