// Generic MITM: find strings A (from alphabet SA, length LA0..LA1) and B (alphabet SB, length LB0..LB1)
// such that fwd(fwd(START, PRE + A), B + POST) == TARGET, i.e. fwd(START, PRE + A) == unwind(TARGET, B + POST).
// usage: mitmc START TARGET PRE POST SA LA0 LA1 SB LB0 LB1
// alphabet keywords: LOWER UPPER ALPHA ALNUM PRINTABLE or a literal string; "CAP+LOWER" means first char upper then lower.
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define P 0x100000001b3ULL
static uint64_t PINV;
static uint64_t inv64(uint64_t a) {
    uint64_t x = a;
    for (int i = 0; i < 6; i++) x *= 2 - a * x;
    return x;
}

static const char *alpha(const char *k) {
    static char buf[4][256];
    static int n = 0;
    char *b = buf[n++ & 3];
    int j = 0;
    if (!strcmp(k, "LOWER")) {
        for (int c = 'a'; c <= 'z'; c++) b[j++] = c;
    } else if (!strcmp(k, "UPPER")) {
        for (int c = 'A'; c <= 'Z'; c++) b[j++] = c;
    } else if (!strcmp(k, "ALPHA")) {
        for (int c = 'a'; c <= 'z'; c++) b[j++] = c;
        for (int c = 'A'; c <= 'Z'; c++) b[j++] = c;
    } else if (!strcmp(k, "ALNUM_")) {
        for (int c = 'a'; c <= 'z'; c++) b[j++] = c;
        for (int c = 'A'; c <= 'Z'; c++) b[j++] = c;
        for (int c = '0'; c <= '9'; c++) b[j++] = c;
        b[j++] = '_';
    } else if (!strcmp(k, "PRINTABLE")) {
        for (int c = 32; c < 127; c++) b[j++] = c;
    } else {
        strcpy(b, k);
        return b;
    }
    b[j] = 0;
    return b;
}

// hash table of forward states
typedef struct {
    uint64_t key;
    uint64_t code;  // encoded string: index in mixed radix
    int len;
} Ent;
static Ent *tab;
static uint64_t tabmask;

static void put(uint64_t key, uint64_t code, int len) {
    uint64_t i = (key * 0x9E3779B97F4A7C15ULL) & tabmask;
    while (tab[i].len >= 0) i = (i + 1) & tabmask;
    tab[i].key = key;
    tab[i].code = code;
    tab[i].len = len;
}

static const char *SA, *SB;
static int na, nb;
static const char *PRE, *POST;
static uint64_t START, TARGET;

static void decode(const char *S, int n, uint64_t code, int len, char *out) {
    for (int i = len - 1; i >= 0; i--) {
        out[i] = S[code % n];
        code /= n;
    }
    out[len] = 0;
}

static long long nf = 0;
static void gen_fwd(uint64_t h, int depth, int lo, int hi, uint64_t code) {
    if (depth >= lo) {
        put(h, code, depth);
        nf++;
    }
    if (depth == hi) return;
    for (int i = 0; i < na; i++) gen_fwd((h ^ (unsigned char)SA[i]) * P, depth + 1, lo, hi, code * na + i);
}

static long long nm = 0;
// backward: we build B right-to-left; state h is the state before the chars built so far (i.e., unwind(TARGET, B_suffix+POST))
static char bbuf[64];
static void gen_bwd(uint64_t h, int depth, int lo, int hi) {
    if (depth >= lo) {
        uint64_t i = (h * 0x9E3779B97F4A7C15ULL) & tabmask;
        while (tab[i].len >= 0) {
            if (tab[i].key == h) {
                char a[64];
                decode(SA, na, tab[i].code, tab[i].len, a);
                printf("MATCH A='%s' B='%.*s'\n", a, depth, bbuf + 64 - depth);
                fflush(stdout);
                nm++;
            }
            i = (i + 1) & tabmask;
        }
    }
    if (depth == hi) return;
    for (int i = 0; i < nb; i++) {
        unsigned char c = SB[i];
        bbuf[64 - depth - 1] = c;
        gen_bwd((h * PINV) ^ c, depth + 1, lo, hi);
    }
}

int main(int argc, char **argv) {
    if (argc < 11) {
        fprintf(stderr, "usage\n");
        return 1;
    }
    PINV = inv64(P);
    START = strtoull(argv[1], NULL, 16);
    TARGET = strtoull(argv[2], NULL, 16);
    PRE = argv[3];
    POST = argv[4];
    SA = alpha(argv[5]);
    na = strlen(SA);
    int la0 = atoi(argv[6]), la1 = atoi(argv[7]);
    SB = alpha(argv[8]);
    nb = strlen(SB);
    int lb0 = atoi(argv[9]), lb1 = atoi(argv[10]);
    // size table
    double cnt = 0, p = 1;
    for (int l = 0; l <= la1; l++) {
        if (l >= la0) cnt += p;
        p *= na;
    }
    uint64_t sz = 1;
    while (sz < (uint64_t)(cnt * 2)) sz <<= 1;
    tab = malloc(sz * sizeof(Ent));
    for (uint64_t i = 0; i < sz; i++) tab[i].len = -1;
    tabmask = sz - 1;
    uint64_t h = START;
    for (const char *q = PRE; *q; q++) h = (h ^ (unsigned char)*q) * P;
    gen_fwd(h, 0, la0, la1, 0);
    fprintf(stderr, "forward states: %lld (table %llu)\n", nf, (unsigned long long)sz);
    uint64_t t = TARGET;
    for (int i = strlen(POST) - 1; i >= 0; i--) t = (t * PINV) ^ (unsigned char)POST[i];
    gen_bwd(t, 0, lb0, lb1);
    fprintf(stderr, "matches: %lld\n", nm);
    return 0;
}

