#!/usr/bin/env python3
"""Find the head of the call Value Debug: START + V1 + '(' + V2 + ' { ' + F1 + ': "rgb", ' + F2 + ': [' + nums."""
import sys
sys.path.insert(0, "/tmp/hatch_search")
from var_mitm import fwd, unwind, START

GD = 0x950dd2adaad62fc6  # state after head + 'Number(255.0), Number(0.0), Number('
words = sorted(set(w.strip() for w in open("/tmp/hatch_search/words.txt") if w.strip()))
fset = {}
for v1 in words:
    for op in ["(", " { ", "("]:
        fset[fwd(START, (v1 + op).encode())] = v1 + op
fset[START] = ""
mids = []
FN = ["name", "func", "function", "fun", "fname", "callee", "ident", "id", "op", "f", "head", "kind"]
AN = ["args", "arguments", "params", "argv", "values", "items", "inner", "body", "list", "parts", "terms"]
for f1 in FN:
    for f2 in AN:
        mids.append(' { %s: "rgb", %s: [' % (f1, f2))
        mids.append(' { %s: "rgb", %s: Tuple([' % (f1, f2))
mids.append('("rgb", [')
mids.append('(Ident("rgb"), [')
found = 0
for mid in mids:
    tgt = unwind(GD, (mid + "Number(255.0), Number(0.0), Number(").encode())
    for v2 in words + [""]:
        s = unwind(tgt, v2.encode())
        if s in fset:
            print("MATCH", repr(fset[s] + v2 + mid))
            found += 1
print("done", found)

#!/usr/bin/env python3
"""Find the head H of the call Value: fwd(START, H) == 0x0a3bf2c74dd0edd2, H ends with '<field>: "'."""
import sys
sys.path.insert(0, "/tmp/hatch_search")
from var_mitm import fwd, unwind, START

GH = 0x0a3bf2c74dd0edd2
words = sorted(set(w.strip() for w in open("/tmp/hatch_search/words.txt") if w.strip()))
fset = {START: ""}
for v1 in words:
    for op in ["(", " { "]:
        fset[fwd(START, (v1 + op).encode())] = v1 + op
FN = ["name", "func", "function", "fun", "fname", "callee", "ident", "id", "op", "f", "head", "kind"]
found = 0
for f in FN + words:
    for v2 in words + [""]:
        for mid in [' { %s: "' % f]:
            s = unwind(GH, (v2 + mid).encode())
            if s in fset:
                print("MATCH", repr(fset[s] + v2 + mid))
                found += 1
print("done", found)

// Backward DFS: find V = [A-Z][a-z]{0,L} (optionally [A-Z][a-z]{0,L1}[A-Z][a-z]{0,L2}) such that
// unwind(T, V) is in a forward set loaded from a file of "hexstate label" lines.
// usage: camelbf TARGETHEX L forwardfile [L2]
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <omp.h>

#define P 0x100000001b3ULL
static uint64_t PINV;
static uint64_t inv64(uint64_t a) {
    uint64_t x = a;
    for (int i = 0; i < 6; i++) x *= 2 - a * x;
    return x;
}

static uint64_t *keys;
static char **labels;
static uint64_t mask;

static int lookup(uint64_t k) {
    uint64_t i = (k * 0x9E3779B97F4A7C15ULL) & mask;
    while (labels[i]) {
        if (keys[i] == k) return (int)i;
        i = (i + 1) & mask;
    }
    return -1;
}

static int L, L2;

// buf holds the chars of V from position pos to end (right-aligned in buf[0..63])
static void report(const char *buf, int pos, int idx) {
#pragma omp critical
    {
        printf("MATCH %s + '%.*s'\n", labels[idx], 64 - pos, buf + pos);
        fflush(stdout);
    }
}

// h = state before the chars buf[pos..64)
static void dfs_lower(uint64_t h, char *buf, int pos, int depth, int maxd, int stage) {
    // try uppercase start here
    for (int u = 'A'; u <= 'Z'; u++) {
        uint64_t g = (h * PINV) ^ (uint64_t)u;
        buf[pos - 1] = (char)u;
        int idx = lookup(g);
        if (idx >= 0) report(buf, pos - 1, idx);
        if (stage == 2) {
            // second (leading) camel part: lower chars then upper
            dfs_lower(g, buf, pos - 1, 0, L, 1);
        }
    }
    if (depth == maxd) return;
    for (int c = 'a'; c <= 'z'; c++) {
        buf[pos - 1] = (char)c;
        dfs_lower((h * PINV) ^ (uint64_t)c, buf, pos - 1, depth + 1, maxd, stage);
    }
}

int main(int argc, char **argv) {
    PINV = inv64(P);
    uint64_t T = strtoull(argv[1], NULL, 16);
    L = atoi(argv[2]);
    L2 = argc > 4 ? atoi(argv[4]) : -1;
    FILE *f = fopen(argv[3], "r");
    int n = 0, cap = 1 << 16;
    uint64_t *ks = malloc(cap * sizeof(uint64_t));
    char **ls = malloc(cap * sizeof(char *));
    char line[512];
    while (fgets(line, sizeof line, f)) {
        char *sp = strchr(line, ' ');
        if (!sp) continue;
        *sp = 0;
        char *lab = sp + 1;
        lab[strcspn(lab, "\n")] = 0;
        if (n == cap) {
            cap *= 2;
            ks = realloc(ks, cap * sizeof(uint64_t));
            ls = realloc(ls, cap * sizeof(char *));
        }
        ks[n] = strtoull(line, NULL, 16);
        ls[n] = strdup(lab);
        n++;
    }
    uint64_t sz = 1;
    while (sz < (uint64_t)n * 4) sz <<= 1;
    keys = calloc(sz, sizeof(uint64_t));
    labels = calloc(sz, sizeof(char *));
    mask = sz - 1;
    for (int i = 0; i < n; i++) {
        uint64_t j = (ks[i] * 0x9E3779B97F4A7C15ULL) & mask;
        while (labels[j]) j = (j + 1) & mask;
        keys[j] = ks[i];
        labels[j] = ls[i];
    }
    fprintf(stderr, "loaded %d forward states\n", n);
    // parallel over the last character
#pragma omp parallel for schedule(dynamic)
    for (int c = 'a'; c <= 'z' + 1; c++) {
        char buf[64];
        if (c == 'z' + 1) {
            // V of length 1 (just an uppercase letter) or ending in uppercase handled in dfs at depth 0
            dfs_lower(T, buf, 64, L, L, L2 >= 0 ? 2 : 1);
            continue;
        }
        buf[63] = (char)c;
        uint64_t h = (T * PINV) ^ (uint64_t)c;
        dfs_lower(h, buf, 63, 1, (L2 >= 0 ? L2 : L), L2 >= 0 ? 2 : 1);
    }
    fprintf(stderr, "done\n");
    return 0;
}

